test('REQ-1-3-2#3: REQ-1-3-2 -the requested workflow', async ({ page }) => {
  const fileName = 'filter-' + u() + '.csv';
  await importCsv(page, fileName, 'Region,Sales\nEast,1200\nNorth,800\n');

  const grid = worksheetGrid(page);
  await grid.getByRole('gridcell', { name: 'A1', exact: true }).hover();
  await page.mouse.down();
  await grid.getByRole('gridcell', { name: 'B3', exact: true }).hover();
  await page.mouse.up();

  await page.getByRole('button', { name: 'Data', exact: true }).click();
  await page.getByRole('menuitem', { name: 'Create filter', exact: true }).click();
  await page.getByRole('button', { name: 'Filter Region', exact: true }).click();
  const dialog = page.getByRole('dialog', { name: 'Filter Region', exact: true });
  await dialog.getByRole('button', { name: 'Clear selection', exact: true }).click();
  await dialog.getByRole('checkbox', { name: 'East', exact: true }).check();
  await dialog.getByRole('button', { name: 'Apply', exact: true }).click();

  await expect(worksheetGrid(page).getByRole('gridcell', { name: 'A3', exact: true })).not.toBeVisible();

  const download = await downloadCsv(page);
  const text = await csvText(download);
  expect(text).toContain('North');

  await expect(page.getByRole('button', { name: 'Filter Region', exact: true })).toBeVisible();
  await page.reload();
  await expect(page.getByRole('button', { name: 'Filter Region', exact: true })).toBeVisible();
  await expect(worksheetGrid(page).getByRole('gridcell', { name: 'A3', exact: true })).not.toBeVisible();
});

test('REQ-2-2-2#4: REQ-2-2-2 -the requested workflow', async ({ page }) => {
  await createWorkbook(page);
  await enterCell(page, 'A1', '2');
  await enterCell(page, 'B1', '3');
  await enterCell(page, 'C1', '=A1+B1');
  await selectCell(page, 'C1');
  await expect(page.getByLabel('Formula bar', { exact: true })).toHaveValue('=A1+B1');
  await openColumnMenu(page, 'B');
  await page.getByRole('menuitem', { name: 'Insert 1 column left', exact: true }).click();
  await selectCell(page, 'D1');
  await expectCellValue(page, 'D1', '5');
  await expect(page.getByLabel('Formula bar', { exact: true })).toHaveValue('=A1+C1');
  await page.reload();
  await selectCell(page, 'D1');
  await expectCellValue(page, 'D1', '5');
  await expect(page.getByLabel('Formula bar', { exact: true })).toHaveValue('=A1+C1');
});

test('REQ-3-1-1#2: REQ-3-1-1 -Escape the requested workflow,the requested workflow', async ({ page }) => {
  await createBlankWorkbook(page);
  await setCellViaFormulaBar(page, 'A1', 'Original');

  await cell(page, 'A1').dblclick();
  const edit = page.getByRole('textbox', { name: 'Edit A1', exact: true });
  await edit.fill('Changed');
  await edit.press('Escape');
  await expect(edit).not.toBeVisible();
  await expect(cell(page, 'A1')).toHaveText('Original');
  await cell(page, 'A1').click();
  await expect(formulaBar(page)).toHaveValue('Original');

  await page.reload();
  await expect(cell(page, 'A1')).toHaveText('Original');
});

test('REQ-3-2-1#3: REQ-3-2-1 -the requested workflow', async ({ page }) => {
  await createBlankWorkbook(page);
  await setCellViaFormulaBar(page, 'A1', '2');
  await setCellViaFormulaBar(page, 'B1', '3');
  await setCellViaFormulaBar(page, 'A2', '=A1*$B$1');
  await setCellViaFormulaBar(page, 'B2', '=A1+B1');

  await dragSelect(page, 'A1', 'B2');
  await page.keyboard.press('Control+c');
  await cell(page, 'D1').click();
  await page.keyboard.press('Control+v');

  await expect(cell(page, 'D2')).toHaveText('6');
  await expect(cell(page, 'E2')).toHaveText('5');
  await cell(page, 'D2').click();
  await expect(formulaBar(page)).toHaveValue('=D1*$B$1');
  await cell(page, 'E2').click();
  await expect(formulaBar(page)).toHaveValue('=D1+E1');
  await cell(page, 'A2').click();
  await expect(formulaBar(page)).toHaveValue('=A1*$B$1');
  await cell(page, 'B2').click();
  await expect(formulaBar(page)).toHaveValue('=A1+B1');

  await page.reload();
  await expect(cell(page, 'D2')).toHaveText('6');
  await expect(cell(page, 'E2')).toHaveText('5');
  await cell(page, 'D2').click();
  await expect(formulaBar(page)).toHaveValue('=D1*$B$1');
});

test('REQ-4-1-2: REQ-4-1-2 -the requested workflow', async ({ page }) => {
